import React, { useState, useEffect, useRef } from 'react';
import { useFrame } from '@react-three/fiber';
import { OBJLoader } from 'three/examples/jsm/loaders/OBJLoader';
import * as THREE from 'three';

const ModelLoader = ({ modelPath, nextModelPath, transitionDuration = 2 }) => {
  const [currentGeometry, setCurrentGeometry] = useState(null);
  const [nextGeometry, setNextGeometry] = useState(null);
  const [morphProgress, setMorphProgress] = useState(0);
  const [isTransitioning, setIsTransitioning] = useState(false);

  const groupRef = useRef(null);

  // Load the model geometries
  useEffect(() => {
    if (modelPath) {
      const loader = new OBJLoader();
      loader.load(
        modelPath,
        (obj) => {
          const geometry = extractGeometryFromObject(obj);
          setCurrentGeometry(geometry);
        },
        undefined,
        (error) => console.error('Error loading OBJ:', error)
      );
    }
  }, [modelPath]);

  useEffect(() => {
    if (nextModelPath) {
      const loader = new OBJLoader();
      loader.load(
        nextModelPath,
        (obj) => {
          const geometry = extractGeometryFromObject(obj);
          setNextGeometry(geometry);
          setIsTransitioning(true); // Start transition when new model is loaded
        },
        undefined,
        (error) => console.error('Error loading next OBJ:', error)
      );
    }
  }, [nextModelPath]);

  // Handle transition animation
  useFrame((_, delta) => {
    if (isTransitioning && morphProgress < 1) {
      setMorphProgress((prev) => Math.min(prev + delta / transitionDuration, 1));
    }
    if (morphProgress >= 1) {
      setIsTransitioning(false);
      setCurrentGeometry(nextGeometry);
      setNextGeometry(null);
      setMorphProgress(0);
    }
  });

  // Interpolate between geometries
  const morphGeometry = currentGeometry && nextGeometry ? morphGeometries(currentGeometry, nextGeometry, morphProgress) : currentGeometry;

  return (
    <group ref={groupRef}>
      {morphGeometry && (
        <mesh>
          <bufferGeometry attach="geometry" {...morphGeometry} />
          <meshStandardMaterial color="#ff6347" />
        </mesh>
      )}
    </group>
  );
};

// Function to extract geometry from OBJLoader output
function extractGeometryFromObject(obj) {
  let mergedGeometry = new THREE.BufferGeometry();
  obj.traverse((child) => {
    if (child.isMesh) {
      mergedGeometry = child.geometry.clone(); // Return first mesh found
    }
  });
  return mergedGeometry;
}

// Function to interpolate between geometries
function morphGeometries(geometry1, geometry2, t) {
  const morphGeometry = geometry1.clone();
  const position1 = geometry1.attributes.position.array;
  const position2 = geometry2.attributes.position.array;
  const morphPosition = morphGeometry.attributes.position.array;

  for (let i = 0; i < morphPosition.length; i++) {
    morphPosition[i] = position1[i] + (position2[i] - position1[i]) * t;
  }
  morphGeometry.attributes.position.needsUpdate = true;
  return morphGeometry;
}

export default ModelLoader;
